<script setup lang="ts">
import {download} from '../storage/archive';
import {onMounted,onBeforeUnmount,ref,watch} from 'vue';import {useEditor} from '../stores/editor';import {qualityProfiles} from '../render/quality';import {PlannerScene,type SceneStats} from '../render/scene';
const e=useEditor(),host=ref<HTMLDivElement>(),error=ref(''),cutaway=ref(true),stats=ref<SceneStats>(),photo=ref(false),photoSize=ref('1920x1080'),photoQuality=ref(5),photoBusy=ref(false),photoError=ref('');let scene:PlannerScene|undefined;
onMounted(()=>{try{scene=new PlannerScene(host.value!,{warning:message=>e.error=message,select:id=>{e.selected={kind:'furniture',id};},move:(id,x,z)=>{e.edit('Переместить мебель в 3D',p=>{const f=p.variants.find(v=>v.id===p.activeVariantId)!.furniture.find(f=>f.id===id)!;f.x=x;f.z=z;});},stats:s=>stats.value=s});scene.setQuality(e.quality);scene.update(e.document,e.assets);scene.setMode(e.mode==='2d'?'3d':e.mode);scene.select(e.selected?.kind==='furniture'?e.selected.id:undefined);}catch(reason){scene?.dispose();scene=undefined;error.value='Не удалось запустить 3D. План и редактирование в 2D доступны. '+(reason as Error).message;}});
async function takePhoto(){if(!scene)return;photoBusy.value=true;photoError.value='';try{const [w,h]=photoSize.value.split('x').map(Number);const blob=await scene.capturePng(w,h,photoQuality.value);download(blob,e.document.name+'.png');photo.value=false;}catch(reason){photoError.value=(reason as Error).message;}finally{photoBusy.value=false;}}
watch(()=>e.quality,q=>{localStorage.setItem('house-planner-quality',String(q));scene?.setQuality(q);});
watch([()=>e.document,()=>e.assets],([p,assets])=>scene?.update(p,assets));watch(()=>e.mode,m=>{if(m!=='2d')scene?.setMode(m);});watch(()=>e.selected,s=>scene?.select(s?.kind==='furniture'?s.id:undefined));onBeforeUnmount(()=>scene?.dispose());
</script>
<template><div class="canvas-shell"><div ref="host" class="canvas-host scene-host"/><div v-if="error" class="empty-plan" role="alert"><p>{{error}}</p><button @click="e.mode='2d'">Открыть 2D</button></div><div v-else class="viewport-tools"><select aria-label="Качество 3D" v-model.number="e.quality"><option v-for="q in qualityProfiles" :value="q.level">{{q.level}} · {{q.name}}</option></select><button @click="photo=true">Фото</button><button @click="scene?.fit()">Весь дом</button><button v-if="e.mode!=='walk'" @click="cutaway=scene?.toggleWalls()??true">{{cutaway?'Полные стены':'Срез стен'}}</button></div><div v-if="stats" class="scene-stats" data-testid="scene-stats" :data-geometries="stats.geometries" :data-textures="stats.textures" :data-triangles="stats.triangles">{{stats.triangles.toLocaleString('ru')}} треугольников · {{stats.drawCalls}} вызовов · {{stats.frameMs.toFixed(1)}} мс/кадр · {{stats.geometries}} геометрий · {{stats.textures}} текстур · ≈{{(stats.estimatedBytes/1048576).toFixed(0)}} МБ (оценка)</div><div class="viewport-help">{{e.mode==='walk'?'WASD / стрелки — ходьба · Потяните мышью — осмотр':'Мышь — вращение · Правая кнопка — сдвиг · Колесо — масштаб · Потяните предмет — перенос'}}</div><Teleport to="body"><div v-if="photo" class="modal-backdrop"><section class="import-dialog" role="dialog" aria-modal="true" aria-label="Фото"><h2>Сохранить вид</h2><p>Используется текущий ракурс. После снимка рабочее качество и камера восстанавливаются.</p><fieldset :disabled="photoBusy"><label>Размер снимка<select v-model="photoSize"><option value="1280x720">1280 × 720</option><option value="1920x1080">1920 × 1080</option><option value="2560x1440">2560 × 1440</option></select></label><label>Качество снимка<select v-model.number="photoQuality"><option v-for="q in qualityProfiles" :value="q.level">{{q.level}} · {{q.name}}</option></select></label><div class="toolbar-row"><button class="primary" @click="takePhoto">Сохранить PNG</button><button @click="photo=false">Закрыть</button></div></fieldset><p v-if="photoBusy" role="status">Создание снимка…</p><p v-if="photoError" class="warnings" role="alert">{{photoError}}</p></section></div></Teleport></div></template>
